{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_booth_open",
 "name": "Deadball: the booth, before the first pitch",
 "set": "set_hughson_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "drift",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Hello from the press box at {venue}. I'm {pbp.name}, and {col.name}'s here with me.",
     "We're up in the press box at {venue}. {pbp.name} here, with {col.name}."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{pbp.name} and {col.name}",
     "sub": "The call from {venue}",
     "at": 0.4,
     "for": 5
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{away} come in at {awayRecord}. {home} are {homeRecord}. Neither of them wants to give one away.",
     "{home} are {homeRecord}, {away} {awayRecord}. It's a long season, but they all count."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "awayRecord",
     "op": "has"
    },
    {
     "fact": "homeRecord",
     "op": "has"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "The one I'm watching is {star.name}, {star.said}.",
     "Keep an eye on {star.name}. He's {star.said}."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "star",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "star.name",
     "op": "has"
    },
    {
     "fact": "star.said",
     "op": "has"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{homeStarter.name} has the ball for {home}. If he's sharp early, this is his game.",
     "It starts with {homeStarter.name}. Get through the order once clean and he settles in."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "homeStarter.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That's enough from us. Let's play ball.",
     "Here's the first pitch coming up."
    ]
   },
   "gfx": []
  }
 ]
}
